  'A quarter of the way through the hizb': 'ஹிஸ்பின் கால் பகுதி',
  'A quiet counter for your dhikr': 'உங்கள் திக்ருக்கான அமைதியான எண்ணி',
  'A quiet heads-up before each prayer, so you are not caught out.': 'ஒவ்வொரு தொழுகைக்கும் முன் அமைதியான முன்னறிவிப்பு, நீங்கள் திடுக்கிடாமல் இருக்க.',
  'A quiet heads-up, so you are not caught out.': 'அமைதியான முன்னறிவிப்பு, நீங்கள் திடுக்கிடாமல் இருக்க.',
  'A quiet, tactile dhikr counter': 'அமைதியான, தொடுவுணர் திக்ர் எண்ணி',
  'A reading is counted in pages, the way the Mushaf is printed — 604 of them. Mark the pages you have reached and the rest is worked out here, on your device.': 'ஒரு வாசிப்பு பக்கங்களில் எண்ணப்படுகிறது, முஸ்ஹஃப் அச்சிடப்பட்டபடி — 604 பக்கங்கள். நீங்கள் எட்டிய பக்கங்களைக் குறி, மீதி இங்கே உங்கள் சாதனத்தில் கணக்கிடப்படும்.',
  'A recommended fast. The Prophet ﷺ fasted it and said it expiates the year before it.': 'பரிந்துரைக்கப்பட்ட நோன்பு. நபிகள் பெருமகனார் ﷺ அதை நோற்று, அது முந்தைய ஆண்டுக்குப் பரிகாரம் என்று கூறினார்கள்.',
  'A reminder to yourself — kept only on this device': 'உங்களுக்கான ஒரு நினைவூட்டல் — இந்தச் சாதனத்தில் மட்டுமே வைக்கப்படும்',
  'A reminder will come at': 'ஒரு நினைவூட்டல் வரும்',
  'A required extended vowel.': 'கட்டாய நீட்டிய உயிரெழுத்து.',
  'A rigid itinerary — the crowds will set your pace': 'கடுமையான பயணத் திட்டம் — கூட்டம் உங்கள் வேகத்தை நிர்ணயிக்கும்',
  'A short charging cable and a spare': 'குறுகிய மின்னூட்டக் கம்பியும் ஒரு உதிரியும்',
  'A small pot decanted into your day bag': 'உங்கள் நாள் பையில் மாற்றி ஊற்றப்பட்ட ஒரு சிறு பாத்திரம்',
  'A small shoulder bag — large backpacks are turned away at the gates': 'ஒரு சிறிய தோள்பை — பெரிய முதுகுப்பைகள் வாயில்களில் திருப்பி அனுப்பப்படும்',
  'A spare pair, in case one gives out': 'ஒன்று கெட்டால் என்று ஓர் உதிரி இணை',
  'A stretch of verses, both ends included — for learning a passage.': 'இரு முனைகளும் உள்ளடங்கிய ஒரு வசனத் தொடர் — ஒரு பகுதியைக் கற்க.',
  'A tafsir, not a translation': 'தஃப்ஸீர், மொழிபெயர்ப்பு அல்ல',
  'A thin folding prayer mat and unscented wipes': 'மெல்லிய மடிக்கும் தொழுகை விரிப்பும் மணமற்ற துடைப்பான்களும்',
  'A valid fast requires sincere intention and abstention from invalidators during the fasting day.': 'செல்லுபடியாகும் நோன்புக்கு உளமார்ந்த நிய்யத்தும் நோன்பு நாளில் நோன்பை முறிக்கும் செயல்களைத் தவிர்த்தலும் தேவை.',
  'A verse or hadith each day': 'ஒவ்வொரு நாளும் ஒரு வசனம் அல்லது ஹதீஸ்',
  'A white, clear discharge released at the end of the cycle. The Prophet ﷺ described it to Umm Atiyya as the sign that bleeding has ended, and women of the early generations would send word of it to one another.': 'சுழற்சியின் முடிவில் வெளியேறும் வெள்ளை, தெளிவான சுரப்பு. நபிகள் பெருமகனார் ﷺ அதை உம்மு அதிய்யாவுக்கு இரத்தம் நின்றதன் அறிகுறியாக விவரித்தார்கள், முந்தைய தலைமுறைப் பெண்கள் அதை ஒருவருக்கொருவர் தெரிவித்துக்கொள்வார்கள்.',
  'A word at a time, and every root learned is a door that stays open long after these days have passed. Ten days of ten words is a hundred words carried into the rest of the year.': 'ஒரு நேரத்தில் ஒரு சொல், கற்றுக்கொள்ளும் ஒவ்வொரு மூலச் சொல்லும் இந்த நாட்கள் கடந்து நீண்ட காலத்திற்கும் திறந்திருக்கும் ஒரு கதவு. பத்து நாட்கள் பத்து சொற்கள் என்பது ஆண்டின் மீதிக்குக் கொண்டு செல்லப்படும் நூறு சொற்கள்.',
  'AH': 'ஹி',
  'ALL THREE': 'மூன்றும்',
  'ALL TIME': 'எல்லாக் காலமும்',
  'AMOUNT': 'தொகை',
  'AND IF My servants ask thee about Me - behold, I am near; I respond to the call of him who calls, whenever he calls unto Me: let them, then, respond unto Me, and believe in Me, so that they might follow the right way.': 'என் அடியார்கள் உம்மிடம் என்னைப் பற்றிக் கேட்டால் — இதோ, நான் நெருக்கமாக இருக்கிறேன்; என்னை அழைப்பவரின் அழைப்புக்கு அவர் அழைக்கும்போதெல்லாம் நான் பதிலளிக்கிறேன்: எனவே அவர்கள் எனக்குப் பதிலளிக்கட்டும், என்னை நம்பிக்கை கொள்ளட்டும், அதனால் அவர்கள் நேர் வழியைப் பின்பற்றுவார்கள்.',
  'AND SEE A DOCTOR': 'மற்றும் மருத்துவரை அணுகவும்',
