  'Collections kept for offline': 'இணையமற்ற பயன்பாட்டுக்கு வைக்கப்பட்ட தொகுப்புகள்',
  'Collections, books and saved hadith': 'தொகுப்புகள், நூல்கள் மற்றும் சேமித்த ஹதீஸ்கள்',
