  'Commentary on the Quran, in the language you read it in. Tafsir is one scholar’s reading, not the text itself.': 'நீங்கள் வாசிக்கும் மொழியில் குர்ஆனுக்கான விளக்க உரை. தஃப்ஸீர் என்பது ஓர் அறிஞரின் வாசிப்பு, உரையே அல்ல.',
  'Commentary you have kept': 'நீங்கள் வைத்திருக்கும் விளக்கவுரை',
  'Commonly observed, and disputed. The reports about it are not all sound.': 'பொதுவாகக் கடைப்பிடிக்கப்படுவதும், கருத்து வேறுபாடு உள்ளதும். அது பற்றிய அறிவிப்புகள் எல்லாம் நம்பகமானவை அல்ல.',
  'Compass': 'திசைகாட்டி',
  'Compass point': 'திசைகாட்டிப் புள்ளி',
  'Compiled': 'தொகுக்கப்பட்டது',
  'Complete Surah recitations from published reciters, used when you play a whole Surah rather than verse by verse.': 'வெளியிடப்பட்ட ஓதுபவர்களிடமிருந்து முழு ஸூரா ஓதுதல்கள், வசனந்தோறும் அல்லாமல் முழு ஸூராவையும் இயக்கும்போது பயன்படுத்தப்படும்.',
  'Complete Surah recordings — one continuous track per Surah.': 'முழு ஸூரா பதிவுகள் — ஒவ்வொரு ஸூராவுக்கும் ஒரு தொடர் தடம்.',
  'Complete dryness: nothing at all is seen when checking, so the place remains clean and dry. For many women this is the clearer of the two signs, and it is reached a day or two after the discharge stops.': 'முழு உலர்வு: சரிபார்க்கும்போது ஒன்றுமே தெரிவதில்லை, எனவே இடம் தூய்மையாகவும் உலர்ந்தும் இருக்கும். பல பெண்களுக்கு இரு அறிகுறிகளில் இதுவே தெளிவானது, சுரப்பு நின்று ஒன்று அல்லது இரண்டு நாட்களுக்குப் பின் இது எட்டப்படும்.',
  'Complete journey': 'பயணத்தை நிறைவு செய்',
  'Complete the Quran': 'குர்ஆனை முழுமையாக்கு',
  'Complete the required units, tashahhud, and salawat.': 'தேவையான ரக்அத்கள், தஷஹ்ஹுத் மற்றும் ஸலவாத்தை முடி.',
  'Complete this journey': 'இந்தப் பயணத்தை நிறைவு செய்',
  'Completed': 'நிறைவடைந்தது',
  'Completed journeys': 'நிறைவடைந்த பயணங்கள்',
  'Completed readings': 'நிறைவடைந்த ஓதுதல்கள்',
  'Concise educational overviews with transparent Qur’an and Hadith references. Detailed rulings should be learned from a qualified local scholar.': 'தெளிவான குர்ஆன் மற்றும் ஹதீஸ் மேற்கோள்களுடன் சுருக்கமான கல்வி கண்ணோட்டங்கள். விரிவான சட்டங்கள் தகுதியுள்ள உள்ளூர் அறிஞரிடம் கற்கப்பட வேண்டும்.',
  'Conclude with Witr according to your practice.': 'உங்கள் வழக்கப்படி வித்ருடன் முடி.',
  'Confidence below which a verse counts as weak': 'இதற்குக் கீழ் ஒரு வசனம் பலவீனமாகக் கருதப்படும் நம்பிக்கை',
  'Confirm': 'உறுதி',
