  'Continue to be asked. Nothing is scheduled unless you allow it, and every reminder can be switched off later in Settings.': 'தொடர்ந்து கேட்கப்படும். நீங்கள் அனுமதிக்கும் வரை ஒன்றும் திட்டமிடப்படாது, ஒவ்வொரு நினைவூட்டலையும் பிறகு அமைப்புகளில் முடக்கலாம்.',
  'Continue your reading with a few mindful verses.': 'சில கவனமான வசனங்களுடன் உங்கள் வாசிப்பைத் தொடர்.',
