  'Count privately on this device. Nothing is sent anywhere and no account is needed.': 'இந்தச் சாதனத்தில் தனிப்பட்ட முறையில் எண்ணு. எங்கும் ஒன்றும் அனுப்பப்படுவதில்லை, கணக்கும் தேவையில்லை.',
