  'Curated references open the Arabic text alongside your selected translation.': 'தொகுக்கப்பட்ட மேற்கோள்கள் அரபி உரையை நீங்கள் தேர்வு செய்த மொழிபெயர்ப்புக்குப் பக்கத்தில் திறக்கும்.',
