  'Cycle and purity records, the days after childbirth, and the fasts owed because of them — kept only on this device. Nothing is uploaded and no account is involved.': 'சுழற்சி மற்றும் தூய்மைப் பதிவுகள், பிரசவத்திற்குப் பின் நாட்கள், மற்றும் அவற்றால் கடமையான நோன்புகள் — இந்தச் சாதனத்தில் மட்டுமே வைக்கப்படும். ஒன்றும் பதிவேற்றப்படுவதில்லை, கணக்கும் தேவையில்லை.',
