  'Days': 'நாட்கள்',
  'Days fasted in each month, oldest first.': 'ஒவ்வொரு மாதமும் நோன்பு நோற்ற நாட்கள், பழமையானது முதலில்.',
  'Days missed through hayd or nifas are made up one for one. There is no fidyah on them, because fidyah belongs to the one who cannot make the day up at all. A woman who can fast later fasts later.': 'ஹைள் அல்லது நிஃபாசால் தவறவிட்ட நாட்கள் ஒன்றுக்கு ஒன்றாகக் களா செய்யப்படும். அவற்றில் ஃபித்யா இல்லை, ஏனெனில் ஃபித்யா நாளை முற்றிலும் களா செய்ய முடியாதவருக்குரியது. பிறகு நோற்க முடிந்த ஒரு பெண் பிறகு நோற்பார்.',
  'Days of Ramadan missed through menstruation or post-natal bleeding are made up before the next Ramadan, one day for each day. They do not need to be consecutive, and they may be spread through the year — but they are a debt, so most women keep a running count. This area records those days for you and keeps the scorecard honest as you settle them.': 'மாதவிடாய் அல்லது பிரசவத்திற்குப் பின் இரத்தத்தால் தவறவிட்ட ரமலான் நாட்கள் அடுத்த ரமலானுக்கு முன் ஒரு நாளுக்கு ஒரு நாளாகக் களா செய்யப்படும். அவை தொடர்ச்சியாக இருக்க வேண்டியதில்லை, ஆண்டு முழுவதும் பரவலாக இருக்கலாம் — ஆனால் அவை ஒரு கடன், எனவே பெரும்பாலான பெண்கள் ஓடும் எண்ணிக்கையைப் பராமரிக்கிறார்கள். இந்தப் பகுதி அந்த நாட்களை உங்களுக்காகப் பதிவு செய்து, நீங்கள் அவற்றை நிறைவு செய்யும்போது கணக்கை நேர்மையாக வைத்திருக்கும்.',
