  'Deutsch': 'டாய்ச்சு',
  'Dhikr': 'திக்ர்',
  'Dhikr counter': 'திக்ர் எண்ணி',
  'Dhikr, dua, charity, kindness to family, listening to the Quran, and seeking knowledge all continue. Nothing about these days closes the door to a person’s relationship with Allah — they are part of the worship of a woman’s life, not a suspension of it. Many find the regular adhkar of morning and evening especially valuable here, since the habit continues even when the prayer does not.': 'திக்ர், துஆ, தர்மம், குடும்பத்தாரிடம் அன்பு, குர்ஆனைக் கேட்பது, மற்றும் அறிவை நாடுதல் ஆகிய அனைத்தும் தொடர்கின்றன. இந்த நாட்கள் ஒருவர் அல்லாஹ்வுடன் கொண்டுள்ள உறவுக்கான கதவை மூடுவதில்லை — அவை ஒரு பெண்ணின் வாழ்வின் வழிபாட்டின் ஒரு பகுதி, அதன் இடைநிறுத்தம் அல்ல. பலர் காலை மற்றும் மாலை அத்காரை இங்கே மிகவும் மதிப்புமிக்கதாகக் காண்கிறார்கள், ஏனெனில் தொழுகை இல்லாதபோதும் பழக்கம் தொடர்கிறது.',
  'Dhikr, tasbih and istighfar': 'திக்ர், தஸ்பீஹ் மற்றும் இஸ்திஃபார்',
