  'Next Surah': 'அடுத்த ஸூரா',
  'Next cycle expected in {n} days': 'அடுத்த சுழற்சி {n} நாட்களில் எதிர்பார்க்கப்படுகிறது',
  'Next hadith': 'அடுத்த ஹதீஸ்',
  'Next prayer': 'அடுத்த தொழுகை',
  'Next section': 'அடுத்த பிரிவு',
