  'Reminders for each prayer and for dhikr': 'ஒவ்வொரு தொழுகைக்கும் திக்ருக்கும் நினைவூட்டல்கள்',
  'Reminders of accountability, renewal and the final return to Allah.': 'பொறுப்புணர்வு, புதுப்பித்தல் மற்றும் அல்லாஹ்விடம் இறுதி மீளுதல் ஆகியவற்றின் நினைவூட்டல்கள்.',
