  'Root': 'மூலம்',
  'Rounds completed on this phrase': 'இந்த வாக்கியத்தில் நிறைவு செய்யப்பட்ட சுற்றுகள்',
  'Rounds completed on this phrase: {n}': 'இந்த வாக்கியத்தில் நிறைவு செய்யப்பட்ட சுற்றுகள்: {n}',
  'Rub the body with the hand where the water can reach, and finish by washing the feet.': 'நீர் சென்றடையும் இடங்களில் கையால் உடலைத் தேய்த்து, பாதங்களைக் கழுவி முடி.',
  'Rub the hair gently so water reaches the scalp, then pour three handfuls over the head.': 'நீர் உச்சந்தலையைச் சென்றடைய முடியை மெதுவாகத் தேய்த்து, பிறகு மூன்று கைப்பிடி நீரைத் தலைமீது ஊற்று.',
  'Russian': 'உருசியம்',
