  'Save your Islamic backup': 'உங்கள் இஸ்லாமியக் காப்புப் பிரதியைச் சேமி',
  'Saved': 'சேமிக்கப்பட்டது',
  'Saved ({n})': 'சேமிக்கப்பட்டது ({n})',
  'Saved for installed app': 'நிறுவப்பட்ட செயலிக்குச் சேமிக்கப்பட்டது',
  'Saved for offline': 'இணையமற்ற பயன்பாட்டுக்குச் சேமிக்கப்பட்டது',
  'Saved hadith': 'சேமிக்கப்பட்ட ஹதீஸ்',
  'Saved on this device': 'இந்தச் சாதனத்தில் சேமிக்கப்பட்டது',
  'Saved on this device and applied to every prayer time.': 'இந்தச் சாதனத்தில் சேமிக்கப்பட்டு ஒவ்வொரு தொழுகை நேரத்துக்கும் பயன்படுத்தப்படும்.',
  'Saved on this device.': 'இந்தச் சாதனத்தில் சேமிக்கப்பட்டது.',
  'Saved prayer schedule': 'சேமிக்கப்பட்ட தொழுகை அட்டவணை',
  'Saved rounds will appear here.': 'சேமித்த சுற்றுகள் இங்கே தோன்றும்.',
  'Saved to your bookmarks': 'உங்கள் புக்மார்க்குகளில் சேமிக்கப்பட்டது',
  'Saved. Reminders are scheduled in the installed app.': 'சேமிக்கப்பட்டது. நிறுவப்பட்ட செயலியில் நினைவூட்டல்கள் திட்டமிடப்பட்டன.',
  'Saving…': 'சேமிக்கிறது…',
  'Say it, then check.': 'இதைச் சொல்லி, பிறகு சரிபார்.',
  'Sa‘i between Safa and Marwah': 'ஸஃபா மற்றும் மர்வாவுக்கு இடையே ஸயீ',
  'Scarves that pin easily, and more pins than you think you need': 'எளிதாகக் குத்தக்கூடிய தலைக்குட்டைகள், மற்றும் நீங்கள் நினைப்பதை விட அதிக ஊசிகள்',
  'Schedule': 'அட்டவணை',
  'Scheduling…': 'திட்டமிடுகிறது…',
  'Scheherazade': 'Scheherazade',
  'Scheherazade New': 'Scheherazade New',
  'Scholars differ on which of the two to measure against. The lower threshold brings more wealth into Zakat; take the choice to someone you trust.': 'இரண்டில் எதை அளவிடுவது என்பதில் அறிஞர்கள் வேறுபடுகிறார்கள். குறைந்த வரம்பு அதிக செல்வத்தை ஜகாத்துக்குள் கொண்டுவரும்; தேர்வை நீங்கள் நம்பும் ஒருவரிடம் கொண்டு செல்லுங்கள்.',
  'Scholars differ. Reciting from memory is widely permitted; touching the physical mushaf is not, since it requires purification. On screens and phones the question turns on whether a device counts as a mushaf — many contemporary scholars permit reading and reciting from a phone for that reason, while others advise limiting it to looking and listening. Follow the position of a scholar you trust, and keep the Quran close either way: listening to recitation is open to everyone, in every state.': 'அறிஞர்கள் வேறுபடுகிறார்கள். மனப்பாடத்திலிருந்து ஓதுவது பரவலாக அனுமதிக்கப்பட்டது; பூத முஸ்ஹஃபைத் தொடுவது அல்ல, ஏனெனில் அது தூய்மையைக் கோருகிறது. திரைகளிலும் தொலைபேசிகளிலும் கேள்வி ஒரு சாதனம் முஸ்ஹஃபாகக் கருதப்படுகிறதா என்பதில் திரும்புகிறது — இந்தக் காரணத்திற்காகப் பல சமகால அறிஞர்கள் தொலைபேசியிலிருந்து வாசிப்பதையும் ஓதுவதையும் அனுமதிக்கிறார்கள், மற்றவர்கள் பார்ப்பதோடும் கேட்பதோடு மட்டுப்படுத்த அறிவுறுத்துகிறார்கள். நீங்கள் நம்பும் ஓர் அறிஞரின் நிலைப்பாட்டைப் பின்பற்றுங்கள், எப்படியிருந்தாலும் குர்ஆனை நெருக்கமாக வைத்துக்கொள்ளுங்கள்: ஓதுதலைக் கேட்பது எல்லா நிலைகளிலும் எல்லோருக்கும் திறந்தது.',
  'Script': 'எழுத்து வடிவம்',
  'Script & display': 'எழுத்து வடிவம் & காட்சி',
  'Sealed here before it leaves the device, then handed to whatever you save it with.': 'சாதனத்தை விட்டு வெளியேறுவதற்கு முன் இங்கே முத்திரையிடப்பட்டு, பிறகு நீங்கள் எதில் சேமிக்கிறீர்களோ அதற்கு ஒப்படைக்கப்படும்.',
  'Search': 'தேடு',
