  'Take Ihram before you cross the Miqat': 'மீகாத்தைக் கடப்பதற்கு முன் இஹ்ராம் அணி',
  'Take suhoor and stop by true dawn.': 'ஸஹர் உண்டு உண்மை விடியலில் நிறுத்து.',
  'Tap a chip to drop it, or search for another. Up to three at a time.': 'ஒரு சில்லைக் கைவிடத் தொடு, அல்லது வேறொன்றைத் தேடு. ஒரே நேரத்தில் மூன்று வரை.',
  'Tap a page to take it back. The most recent forty are shown.': 'ஒரு பக்கத்தைத் திரும்பப் பெறத் தொடு. மிக அண்மைய நாற்பது காட்டப்படும்.',
  'Tap any square to see that day.': 'அந்த நாளைக் காண ஏதேனும் ஒரு கட்டத்தைத் தொடு.',
  'Tap to change': 'மாற்றத் தொடு',
  'Tap to choose': 'தேர்வு செய்யத் தொடு',
  'Tap to correct this day.': 'இந்த நாளைச் சரி செய்யத் தொடு.',
