  'Verse {v} continued from page {p}': 'வசனம் {v} பக்கம் {p} இலிருந்து தொடர்கிறது',
  'Verse {v} continues on page {p}': 'வசனம் {v} பக்கம் {p} இல் தொடர்கிறது',
  'Verse, Name and adhkar of the day': 'இன்றைய வசனம், பெயர் மற்றும் அத்கார்',
  'Verse-by-verse files, one track per ayah, with translation audio and reader controls.': 'வசனந்தோறும் கோப்புகள், ஒவ்வொரு வசனத்திற்கும் ஒரு தடம், மொழிபெயர்ப்பு ஒலி மற்றும் வாசிப்புக் கட்டுப்பாடுகளுடன்.',
  'Verse-by-verse: one track for each ayah. Full-Surah: a complete recitation of the Surah.': 'வசனந்தோறும்: ஒவ்வொரு வசனத்திற்கும் ஒரு தடம். முழு ஸூரா: ஸூராவின் முழு ஓதுதல்.',
  'Verses': 'வசனங்கள்',
  'Verses affirming the absolute oneness, independence and incomparability of Allah.': 'அல்லாஹ்வின் முழுமையான ஏகத்துவம், தன்னிறைவு மற்றும் ஒப்பற்ற தன்மையை உறுதிப்படுத்தும் வசனங்கள்.',
  'Verses under this are drawn more often. Anything you flag yourself counts as weak whatever it scores.': 'இதன் கீழுள்ள வசனங்கள் அடிக்கடி எடுக்கப்படும். நீங்களே குறிக்கும் எதுவும் அது எந்த மதிப்பெண் பெற்றாலும் பலவீனமாகக் கருதப்படும்.',
  'Version': 'பதிப்பு',
