  'Visa or Nusuk permit — printed, and saved offline on your phone': 'விசா அல்லது நுஸுக் அனுமதி — அச்சிடப்பட்டு, உங்கள் தொலைபேசியில் இணையமற்ற நிலையில் சேமிக்கப்பட்டது',
