  'Your ID card and a little cash': 'உங்கள் அடையாள அட்டையும் சிறிது பணமும்',
  'Your PIN is saved on this device.': 'உங்கள் PIN இந்தச் சாதனத்தில் சேமிக்கப்பட்டுள்ளது.',
  'Your Quran': 'உங்கள் குர்ஆன்',
  'Your Quran time': 'உங்கள் குர்ஆன் நேரம்',
